('techpeople.lifecycle.renew.workspace','techpeople','lifecycle','manage','workspace','Solicitar renovação','Nova vigência assinada e aprovação gestor e CEO.',true),
('techpeople.lifecycle.replace.workspace','techpeople','lifecycle','manage','workspace','Solicitar substituição','Substituto admitido; sobreposição explícita.',true),
('techpeople.lifecycle.end_allocation.workspace','techpeople','lifecycle','manage','workspace','Solicitar fim de alocação','Origem selecionada, corte inclusivo.',true),
('techpeople.lifecycle.end_employment.workspace','techpeople','lifecycle','manage','workspace','Solicitar fim de vínculo','Não desliga pessoa nem membership.',true),
('techpeople.lifecycle.approve.workspace','techpeople','lifecycle','approve','workspace','Decidir ciclo de alocação','Gestor e CEO nomeados, sem autoaprovação.',true),
('techpeople.lifecycle.execute.workspace','techpeople','lifecycle','manage','workspace','Executar ciclo aprovado','Revalidação transacional.',true) ON CONFLICT(key) DO NOTHING;
CREATE TABLE public.hiring_lifecycle_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),engagement_id uuid NOT NULL REFERENCES public.hiring_engagements(id),allocation_id uuid REFERENCES public.people_allocations(id),kind text NOT NULL CHECK(kind IN('renew','replace','end_allocation','end_employment')),effective_date date NOT NULL,starts_at date,ends_at date,replacement_id uuid REFERENCES public.hiring_engagements(id),overlap boolean NOT NULL DEFAULT false,reason text NOT NULL,requested_by uuid NOT NULL,source_revision integer NOT NULL,policy_revision integer NOT NULL,source_hash text NOT NULL,snapshot jsonb NOT NULL,revision integer NOT NULL DEFAULT 1,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected','executed')),result jsonb,created_at timestamptz NOT NULL DEFAULT now(),executed_at timestamptz,UNIQUE(engagement_id,source_hash));
GRANT SELECT(id,workspace_id,engagement_id,allocation_id,kind,effective_date,starts_at,ends_at,replacement_id,overlap,reason,requested_by,source_revision,policy_revision,source_hash,revision,status,result,created_at,executed_at) ON public.hiring_lifecycle_requests TO authenticated;GRANT ALL ON public.hiring_lifecycle_requests TO service_role;
ALTER TABLE public.hiring_lifecycle_requests ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.hiring_lifecycle_steps(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id uuid NOT NULL REFERENCES public.workspaces(id),request_id uuid NOT NULL REFERENCES public.hiring_lifecycle_requests(id),stage text NOT NULL CHECK(stage IN('manager','ceo')),position integer NOT NULL,approver_id uuid NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN('pending','approved','rejected')),decided_by uuid,decided_at timestamptz,note text,UNIQUE(request_id,stage));
GRANT SELECT ON public.hiring_lifecycle_steps TO authenticated;GRANT ALL ON public.hiring_lifecycle_steps TO service_role;
ALTER TABLE public.hiring_lifecycle_steps ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.hiring_engagements ADD COLUMN lifecycle_predecessor_id uuid REFERENCES public.hiring_engagements(id),ADD COLUMN lifecycle_request_id uuid UNIQUE REFERENCES public.hiring_lifecycle_requests(id);
ALTER TABLE public.people_allocations ADD COLUMN lifecycle_request_id uuid REFERENCES public.hiring_lifecycle_requests(id),ADD COLUMN lifecycle_predecessor_id uuid REFERENCES public.people_allocations(id);
CREATE UNIQUE INDEX hiring_lifecycle_result_allocation ON public.people_allocations(lifecycle_request_id) WHERE lifecycle_request_id IS NOT NULL;
CREATE INDEX hiring_lifecycle_person_requests ON public.hiring_lifecycle_requests(workspace_id,engagement_id,created_at DESC);
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_access(w uuid,p_engagement uuid,p_action text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT coalesce(p_action IN('view','renew','replace','end_allocation','end_employment','approve','execute') AND public.hiring_employment_access(w,'techpeople.lifecycle.'||p_action||'.workspace') AND EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=auth.uid() AND status='active') AND EXISTS(SELECT 1 FROM hiring_engagements e WHERE e.id=p_engagement AND e.workspace_id=w AND public.hr_record_access('people','view',e.person_id) AND(p_action='view' OR public.hr_record_access('people','update',e.person_id))),false) $$;
REVOKE ALL ON FUNCTION public.hiring_lifecycle_access(uuid,uuid,text) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.hiring_lifecycle_access(uuid,uuid,text) TO authenticated;
CREATE POLICY hiring_lifecycle_read ON public.hiring_lifecycle_requests FOR SELECT TO authenticated USING(public.hiring_lifecycle_access(workspace_id,engagement_id,'view'));
CREATE POLICY hiring_lifecycle_step_read ON public.hiring_lifecycle_steps FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM hiring_lifecycle_requests r WHERE r.id=request_id AND r.workspace_id=hiring_lifecycle_steps.workspace_id AND public.hiring_lifecycle_access(r.workspace_id,r.engagement_id,'view')));
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_document(w uuid,p_contract uuid,p_person uuid,p_entity uuid,p_start date,p_end date) RETURNS text LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE c contracts;e hiring_contract_evidence;d esign_documents;BEGIN
 SELECT * INTO c FROM contracts WHERE id=p_contract AND workspace_id=w FOR SHARE;
 IF c.id IS NULL OR c.contracting_legal_entity_id IS DISTINCT FROM p_entity OR c.status::text NOT IN('active','renewing') OR c.starts_at IS NULL OR c.starts_at>p_start OR(c.ends_at IS NOT NULL AND(p_end IS NULL OR c.ends_at<p_end)) THEN RAISE EXCEPTION 'Contrato revisado deve cobrir todo o novo período e a entidade WK.';END IF;
 IF p_person IS NOT NULL AND(c.role::text<>'client' OR c.hiring_person_id IS DISTINCT FROM p_person) THEN RAISE EXCEPTION 'Contrato de compra deve pertencer ao profissional admitido.';END IF;
 IF NOT public.work_record_access('techcontracts.contracts',c.id,'view') THEN RAISE EXCEPTION 'Sem leitura do contrato.' USING ERRCODE='42501';END IF;
 FOR e IN SELECT * FROM hiring_contract_evidence WHERE contract_id=c.id AND workspace_id=w AND revoked_at IS NULL AND contract_hash=public.hiring_contract_fingerprint(c.id) FOR SHARE LOOP
 IF e.kind='external' AND e.signed_on<=current_date AND EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='contract-signature-evidence' AND name=e.file_path AND user_metadata->>'sha256'=e.file_hash) THEN RETURN e.id::text;END IF;
 IF e.kind='native' THEN SELECT * INTO d FROM esign_documents WHERE id=e.document_id AND workspace_id=w FOR SHARE;
 IF d.status::text='completed' AND d.sealed_at IS NOT NULL AND d.completed_at IS NOT NULL AND d.content_hash=e.document_hash AND encode(extensions.digest(convert_to(d.body,'UTF8'),'sha256'),'hex')=e.document_hash AND(d.expires_at IS NULL OR d.completed_at<=d.expires_at) AND NOT EXISTS(SELECT 1 FROM ats_offers WHERE esign_document_id=d.id) AND NOT EXISTS(SELECT 1 FROM esign_signers WHERE document_id=d.id AND(workspace_id<>w OR status::text<>'signed' OR signed_at IS NULL)) AND EXISTS(SELECT 1 FROM esign_signers WHERE id=e.customer_signer_id AND document_id=d.id AND workspace_id=w AND status::text='signed') AND EXISTS(SELECT 1 FROM esign_signers WHERE id=e.issuer_signer_id AND document_id=d.id AND workspace_id=w AND status::text='signed') THEN RETURN e.id::text;END IF;
 END IF;END LOOP;RAISE EXCEPTION 'Assinatura verificável da versão revisada ausente ou revogada.';
END $$;
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_actor_scope(w uuid,p_engagement uuid,p_actor uuid,p_action text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE claims text;sub text;uid text;allowed boolean;BEGIN
 claims:=current_setting('request.jwt.claims',true);sub:=current_setting('request.jwt.claim.sub',true);uid:=current_setting('request.uid',true);
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',p_actor,'role','authenticated')::text,true);PERFORM set_config('request.jwt.claim.sub',p_actor::text,true);PERFORM set_config('request.uid',p_actor::text,true);
 allowed:=public.hiring_lifecycle_access(w,p_engagement,p_action) AND public.hiring_lifecycle_access(w,p_engagement,'view');
 PERFORM set_config('request.jwt.claims',coalesce(claims,''),true);PERFORM set_config('request.jwt.claim.sub',coalesce(sub,''),true);PERFORM set_config('request.uid',coalesce(uid,''),true);RETURN allowed;
END $$;
REVOKE ALL ON FUNCTION public.hiring_lifecycle_actor_scope(uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated;
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_validate(w uuid,p_engagement uuid,p_allocation uuid,p_kind text,p_effective date,p_start date,p_end date,p_replacement uuid,p_overlap boolean,p_reason text,p_requester uuid,p_action text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE e hiring_engagements;a people_allocations;b hiring_engagements;j ats_jobs;p hiring_area_policies;m uuid;c uuid;u uuid;s jsonb;proof jsonb:='{}';BEGIN
 PERFORM id FROM hiring_engagements WHERE id=p_engagement AND workspace_id=w FOR UPDATE;
 IF NOT public.hiring_lifecycle_access(w,p_engagement,'view') OR NOT public.hiring_lifecycle_access(w,p_engagement,p_action) THEN RAISE EXCEPTION 'Sem permissão para este ciclo.' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT 1 FROM hiring_workspace_settings WHERE workspace_id=w AND lifecycle_gate_enabled) THEN RAISE EXCEPTION 'Ciclo governado ainda desativado neste workspace.';END IF;
 SELECT * INTO e FROM hiring_engagements WHERE id=p_engagement AND workspace_id=w FOR UPDATE;SELECT * INTO j FROM ats_jobs WHERE id=e.job_id AND workspace_id=w FOR SHARE;SELECT * INTO p FROM hiring_area_policies WHERE area_id=j.hiring_area_id AND workspace_id=w FOR SHARE;
 IF e.status<>'active' OR NOT j.hiring_governed OR p.area_id IS NULL THEN RAISE EXCEPTION 'Vínculo ativo e gestor/CEO configurados são obrigatórios; área sem aprovador permanece bloqueada.';END IF;
 IF p_effective IS NULL OR p_effective<e.starts_at OR length(trim(coalesce(p_reason,''))) NOT BETWEEN 10 AND 2000 THEN RAISE EXCEPTION 'Informe corte inclusivo e justificativa válida.';END IF;
 IF p_kind<>'end_employment' AND NOT(p_kind='renew' AND p_allocation IS NULL) THEN SELECT * INTO a FROM people_allocations WHERE id=p_allocation AND hiring_engagement_id=e.id AND workspace_id=w FOR UPDATE;
 IF a.id IS NULL OR a.status::text NOT IN('active','paused') OR a.starts_at>p_effective OR(a.ends_at IS NOT NULL AND a.ends_at<p_effective) THEN RAISE EXCEPTION 'Selecione alocação vigente desta origem no corte.';END IF;
 IF NOT public.hr_record_access('person_allocations','update',e.person_id) THEN RAISE EXCEPTION 'Sem permissão para alocação.' USING ERRCODE='42501';END IF;END IF;
 IF p_kind IN('end_allocation','replace','end_employment') AND EXISTS(SELECT 1 FROM project_time_entries t JOIN people_allocations x ON (x.id=t.allocation_id OR(t.allocation_id IS NULL AND t.project_id=x.project_id AND t.user_id=(SELECT profile_id FROM people WHERE id=x.person_id))) WHERE x.workspace_id=w AND x.hiring_engagement_id=e.id AND(p_kind='end_employment' OR x.id=a.id) AND t.entry_date>p_effective) THEN RAISE EXCEPTION 'Há horas posteriores ao corte. Concilie explicitamente antes de encerrar; não podem ficar órfãs.';END IF;
 IF p_kind='end_employment' AND(e.ends_at IS NOT NULL AND p_effective>e.ends_at) THEN RAISE EXCEPTION 'Encerramento não pode ampliar vigência do vínculo.';END IF;
 IF p_kind='end_employment' AND EXISTS(SELECT 1 FROM people_allocations WHERE hiring_engagement_id=e.id AND workspace_id=w AND starts_at>p_effective AND status::text IN('active','paused')) THEN RAISE EXCEPTION 'Revise primeiro as alocações futuras desta origem.';END IF;
 IF p_kind IN('renew','replace') THEN
 IF p_start IS NULL OR p_end IS NULL OR p_end<p_start THEN RAISE EXCEPTION 'Informe novo período finito válido.';END IF;
 IF p_kind='renew' AND(e.ends_at IS NULL OR(a.id IS NOT NULL AND a.ends_at IS DISTINCT FROM e.ends_at) OR coalesce(a.ends_at,e.ends_at) IS NULL OR p_start<>coalesce(a.ends_at,e.ends_at)+1 OR p_effective<>coalesce(a.ends_at,e.ends_at) OR p_replacement IS NOT NULL OR p_overlap) THEN RAISE EXCEPTION 'Renovação cria período seguinte sem sobrescrever anterior nem sobrepor.';END IF;
 b:=e;
 IF p_kind='replace' THEN SELECT * INTO b FROM hiring_engagements WHERE id=p_replacement AND workspace_id=w FOR UPDATE;
 IF b.id IS NULL OR b.id=e.id OR b.person_id=e.person_id OR b.status<>'active' OR b.legal_entity_id<>e.legal_entity_id OR b.purpose<>e.purpose OR b.commercial_contract_id IS DISTINCT FROM e.commercial_contract_id OR b.starts_at>p_start OR(b.ends_at IS NOT NULL AND b.ends_at<p_end) OR NOT EXISTS(SELECT 1 FROM people WHERE id=b.person_id AND workspace_id=w AND status::text='active' AND NOT archived AND hire_date<=p_start) THEN RAISE EXCEPTION 'Substituto deve estar admitido no mesmo contexto WK/contrato e período.';END IF;
 IF NOT public.hr_record_access('people','view',b.person_id) OR NOT public.hr_record_access('person_allocations','create',b.person_id) THEN RAISE EXCEPTION 'Sem escopo do substituto.' USING ERRCODE='42501';END IF;
 IF (NOT p_overlap AND p_start<>p_effective+1) OR(p_overlap AND(p_start>p_effective OR p_start<a.starts_at)) THEN RAISE EXCEPTION 'Sobreposição precisa ser explícita no pedido e aprovada.';END IF;END IF;
 IF p_kind='replace' AND((b.ends_at IS NOT NULL AND p_end>b.ends_at) OR p_start<b.starts_at) THEN RAISE EXCEPTION 'Novo período excede vínculo admitido; revise o vínculo e os contratos previamente.';END IF;
 IF NOT public.hr_record_access('person_allocations','create',b.person_id) OR(a.project_id IS NOT NULL AND NOT public.work_record_access('techprojects.projects',a.project_id,'view')) THEN RAISE EXCEPTION 'Sem acesso à nova alocação/projeto.' USING ERRCODE='42501';END IF;
 proof:=jsonb_build_object('purchase',public.hiring_lifecycle_document(w,b.purchase_contract_id,b.person_id,b.legal_entity_id,p_start,p_end),'purchase_hash',public.hiring_contract_fingerprint(b.purchase_contract_id));
 IF b.purpose='client' THEN IF public.hiring_contract_signature_reason(b.commercial_contract_id,w,j.deal_id) IS NOT NULL THEN RAISE EXCEPTION 'Contrato comercial sem assinatura revisada válida.';END IF;
 proof:=proof||jsonb_build_object('commercial',public.hiring_lifecycle_document(w,b.commercial_contract_id,NULL,b.legal_entity_id,p_start,p_end),'commercial_hash',public.hiring_contract_fingerprint(b.commercial_contract_id));END IF;END IF;
 IF p.manager_id=p.ceo_id THEN RAISE EXCEPTION 'Gestor e CEO exigem decisões independentes.';END IF;
 m:=CASE WHEN p.manager_id=p_requester THEN p.manager_delegate_id ELSE p.manager_id END;c:=CASE WHEN p.ceo_id=p_requester THEN p.ceo_delegate_id ELSE p.ceo_id END;
 IF m=c THEN RAISE EXCEPTION 'Gestor e CEO exigem decisões independentes.';END IF;
 FOREACH u IN ARRAY ARRAY[m,c] LOOP IF u IS NULL OR u=p_requester OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=u AND status='active') OR NOT public.user_has_permission(u,w,'techpeople.lifecycle.approve.workspace') OR NOT public.user_has_permission(u,w,'techpeople.lifecycle.view.workspace') OR NOT public.hiring_lifecycle_actor_scope(w,e.id,u,'approve') THEN RAISE EXCEPTION 'Aprovador ausente, inativo, solicitante ou sem chave. Configure substituto autorizado.';END IF;END LOOP;
 s:=jsonb_build_object('engagement',to_jsonb(e),'allocation',to_jsonb(a)-ARRAY['updated_at'],'replacement',CASE WHEN p_kind='replace' THEN to_jsonb(b) ELSE NULL END,'job_revision',j.hiring_revision,'policy_revision',p.revision,'manager',m,'ceo',c,'kind',p_kind,'effective',p_effective,'start',p_start,'end',p_end,'overlap',p_overlap,'reason',trim(p_reason),'proof',proof,'purchase_hash',public.hiring_contract_fingerprint(e.purchase_contract_id),'commercial_hash',public.hiring_contract_fingerprint(e.commercial_contract_id));
 RETURN jsonb_build_object('hash',encode(extensions.digest(convert_to(s::text,'UTF8'),'sha256'),'hex'),'revision',e.revision,'policy_revision',p.revision,'manager',m,'ceo',c,'snapshot',s,'effects',jsonb_build_object('kind',p_kind,'source_engagement',e.id,'source_allocation',a.id,'effective_date',p_effective,'new_start',p_start,'new_end',p_end,'replacement',CASE WHEN p_kind='replace' THEN b.id ELSE NULL END,'overlap',p_overlap,'allocation_count',CASE WHEN p_kind='end_employment' THEN(SELECT count(*) FROM people_allocations WHERE hiring_engagement_id=e.id AND workspace_id=w AND status::text IN('active','paused')) WHEN a.id IS NOT NULL THEN 1 ELSE 0 END,'new_period',p_kind='renew','purchase_contract',CASE WHEN p_kind IN('renew','replace') THEN b.purchase_contract_id ELSE e.purchase_contract_id END,'commercial_contract',e.commercial_contract_id,'preserves_person',true,'preserves_other_sources',true,'financial_cancelled',false),'financial_review','Compromissos não são cancelados. Exigem plano Financeiro separado, gestor Financeiro e CEO, seleção explícita de até 100 IDs e revisão da competência trabalhada.');
END $$;
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_preview(w uuid,p_engagement uuid,p_allocation uuid,p_kind text,p_effective date,p_start date,p_end date,p_replacement uuid,p_overlap boolean,p_reason text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN RETURN public.hiring_lifecycle_validate(w,p_engagement,p_allocation,p_kind,p_effective,p_start,p_end,p_replacement,p_overlap,p_reason,auth.uid(),p_kind)-'snapshot';END $$;
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_request(w uuid,p_engagement uuid,p_allocation uuid,p_kind text,p_effective date,p_start date,p_end date,p_replacement uuid,p_overlap boolean,p_reason text,p_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE v jsonb;r uuid;BEGIN
 v:=public.hiring_lifecycle_validate(w,p_engagement,p_allocation,p_kind,p_effective,p_start,p_end,p_replacement,p_overlap,p_reason,auth.uid(),p_kind);
 IF p_hash IS DISTINCT FROM v->>'hash' THEN RAISE EXCEPTION 'Prévia alterada; recalcule antes de solicitar.';END IF;
 SELECT id INTO r FROM hiring_lifecycle_requests WHERE engagement_id=p_engagement AND source_hash=p_hash;IF r IS NOT NULL THEN RETURN r;END IF;
 INSERT INTO hiring_lifecycle_requests(workspace_id,engagement_id,allocation_id,kind,effective_date,starts_at,ends_at,replacement_id,overlap,reason,requested_by,source_revision,policy_revision,source_hash,snapshot) VALUES(w,p_engagement,p_allocation,p_kind,p_effective,p_start,p_end,p_replacement,p_overlap,trim(p_reason),auth.uid(),(v->>'revision')::integer,(v->>'policy_revision')::integer,p_hash,v->'snapshot') RETURNING id INTO r;
 INSERT INTO hiring_lifecycle_steps(workspace_id,request_id,stage,position,approver_id) VALUES(w,r,'manager',1,(v->>'manager')::uuid),(w,r,'ceo',2,(v->>'ceo')::uuid);
 INSERT INTO hiring_employment_events(workspace_id,engagement_id,actor_id,kind,detail) VALUES(w,p_engagement,auth.uid(),'lifecycle_requested',jsonb_build_object('request_id',r,'kind',p_kind,'hash',p_hash));RETURN r;
END $$;
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_revalidate(w uuid,p_request uuid,p_action text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r hiring_lifecycle_requests;v jsonb;BEGIN
 SELECT * INTO r FROM hiring_lifecycle_requests WHERE id=p_request AND workspace_id=w;
 IF r.id IS NULL OR NOT public.hiring_lifecycle_access(w,r.engagement_id,p_action) THEN RAISE EXCEPTION 'Sem permissão para esta solicitação.' USING ERRCODE='42501';END IF;
 PERFORM id FROM hiring_engagements WHERE id=r.engagement_id AND workspace_id=w FOR UPDATE;
 IF NOT public.hiring_lifecycle_actor_scope(w,r.engagement_id,r.requested_by,r.kind) OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=r.requested_by AND status='active') OR NOT public.user_has_permission(r.requested_by,w,'techpeople.lifecycle.'||r.kind||'.workspace') OR NOT public.user_has_permission(r.requested_by,w,'techpeople.lifecycle.view.workspace') THEN RAISE EXCEPTION 'Solicitante perdeu autorização; revise a solicitação.' USING ERRCODE='42501';END IF;
 v:=public.hiring_lifecycle_validate(w,r.engagement_id,r.allocation_id,r.kind,r.effective_date,r.starts_at,r.ends_at,r.replacement_id,r.overlap,r.reason,r.requested_by,p_action);
 IF v->>'hash' IS DISTINCT FROM r.source_hash THEN RAISE EXCEPTION 'Documentos, política ou revisão alterados; obtenha nova prévia e aprovação.';END IF;RETURN v;
END $$;
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_decide(w uuid,p_request uuid,p_revision integer,p_decision text,p_note text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r hiring_lifecycle_requests;s hiring_lifecycle_steps;BEGIN
 PERFORM public.hiring_lifecycle_revalidate(w,p_request,'approve');SELECT * INTO r FROM hiring_lifecycle_requests WHERE id=p_request AND workspace_id=w FOR UPDATE;
 IF r.requested_by=auth.uid() THEN RAISE EXCEPTION 'Solicitante nunca aprova o próprio pedido.' USING ERRCODE='42501';END IF;
 IF p_decision NOT IN('approved','rejected') OR length(trim(coalesce(p_note,''))) NOT BETWEEN 5 AND 2000 THEN RAISE EXCEPTION 'Informe decisão e justificativa.';END IF;
 IF EXISTS(SELECT 1 FROM hiring_lifecycle_steps WHERE request_id=r.id AND decided_by=auth.uid() AND status=p_decision AND note=trim(p_note)) THEN RETURN;END IF;
 IF r.status<>'pending' OR r.revision<>p_revision THEN RAISE EXCEPTION 'Revisão alterada ou solicitação encerrada.';END IF;
 SELECT * INTO s FROM hiring_lifecycle_steps WHERE request_id=r.id AND status='pending' ORDER BY position LIMIT 1 FOR UPDATE;
 IF s.approver_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Aguarde gestor da área e CEO nomeados.' USING ERRCODE='42501';END IF;
 UPDATE hiring_lifecycle_steps SET status=p_decision,decided_by=auth.uid(),decided_at=now(),note=trim(p_note) WHERE id=s.id AND approver_id=auth.uid() AND status='pending';
 UPDATE hiring_lifecycle_requests SET revision=revision+1,status=CASE WHEN p_decision='rejected' THEN 'rejected' WHEN NOT EXISTS(SELECT 1 FROM hiring_lifecycle_steps WHERE request_id=r.id AND status<>'approved') THEN 'approved' ELSE 'pending' END WHERE id=r.id;
 INSERT INTO hiring_employment_events(workspace_id,engagement_id,actor_id,kind,detail) VALUES(w,r.engagement_id,auth.uid(),'lifecycle_'||p_decision,jsonb_build_object('request_id',r.id,'stage',s.stage,'note',trim(p_note)));
END $$;
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_mutation_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE eid uuid;w uuid;r hiring_lifecycle_requests;BEGIN
 IF TG_TABLE_NAME='hiring_engagements' THEN eid:=OLD.id;w:=OLD.workspace_id;
 IF (to_jsonb(NEW)-ARRAY['revision'])=(to_jsonb(OLD)-ARRAY['revision']) THEN RETURN NEW;END IF;
 IF NEW.starts_at IS NOT DISTINCT FROM OLD.starts_at AND NEW.ends_at IS NOT DISTINCT FROM OLD.ends_at AND NEW.status IS NOT DISTINCT FROM OLD.status THEN RETURN NEW;END IF;
 ELSE IF TG_OP='UPDATE' AND OLD.hiring_engagement_id IS NOT NULL AND(NEW.hiring_engagement_id IS DISTINCT FROM OLD.hiring_engagement_id OR NEW.workspace_id IS DISTINCT FROM OLD.workspace_id) THEN RAISE EXCEPTION 'Origem e workspace da alocação governada são imutáveis.';END IF;
 eid:=NEW.hiring_engagement_id;w:=NEW.workspace_id;
 IF TG_OP='UPDATE' AND NEW.lifecycle_request_id IS NOT DISTINCT FROM OLD.lifecycle_request_id AND NEW.lifecycle_predecessor_id IS NOT DISTINCT FROM OLD.lifecycle_predecessor_id AND NEW.starts_at IS NOT DISTINCT FROM OLD.starts_at AND NEW.ends_at IS NOT DISTINCT FROM OLD.ends_at AND NEW.status IS NOT DISTINCT FROM OLD.status AND NEW.can_track_time IS NOT DISTINCT FROM OLD.can_track_time THEN RETURN NEW;END IF;
 IF TG_OP='INSERT' AND NEW.lifecycle_predecessor_id IS NULL AND NEW.lifecycle_request_id IS NULL AND NOT EXISTS(SELECT 1 FROM people_allocations x WHERE x.hiring_engagement_id=eid AND x.project_id IS NOT DISTINCT FROM NEW.project_id) THEN RETURN NEW;END IF;END IF;
 IF eid IS NULL OR NOT EXISTS(SELECT 1 FROM hiring_workspace_settings WHERE workspace_id=w AND lifecycle_gate_enabled) THEN RETURN NEW;END IF;
 SELECT * INTO r FROM hiring_lifecycle_requests WHERE id::text=current_setting('app.hiring_lifecycle',true) AND workspace_id=w AND status='approved';
 IF r.id IS NULL OR(eid<>r.engagement_id AND eid IS DISTINCT FROM r.replacement_id AND NOT EXISTS(SELECT 1 FROM hiring_engagements WHERE id=eid AND lifecycle_request_id=r.id)) OR NOT public.hiring_lifecycle_access(w,r.engagement_id,'execute') THEN RAISE EXCEPTION 'Use o ciclo governado com prévia e aprovação gestor → CEO; encerramento legado bloqueado.' USING ERRCODE='42501';END IF;RETURN NEW;
END $$;
CREATE TRIGGER zzzzzzz_hiring_lifecycle BEFORE UPDATE ON public.hiring_engagements FOR EACH ROW EXECUTE FUNCTION public.hiring_lifecycle_mutation_guard();
CREATE TRIGGER zzzzzzz_hiring_lifecycle BEFORE INSERT OR UPDATE ON public.people_allocations FOR EACH ROW EXECUTE FUNCTION public.hiring_lifecycle_mutation_guard();
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_execute(w uuid,p_request uuid,p_revision integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE r hiring_lifecycle_requests;a people_allocations;b hiring_engagements;old_e hiring_engagements;g hiring_access_grants;v hiring_access_model_versions;newid uuid;new_e uuid;new_set uuid;assignment uuid;result_value jsonb;BEGIN
 SELECT * INTO r FROM hiring_lifecycle_requests WHERE id=p_request AND workspace_id=w;
 IF r.id IS NULL OR NOT public.hiring_lifecycle_access(w,r.engagement_id,'execute') OR NOT public.hiring_lifecycle_access(w,r.engagement_id,'view') THEN RAISE EXCEPTION 'Sem permissão para executar.' USING ERRCODE='42501';END IF;
 PERFORM id FROM hiring_engagements WHERE id=r.engagement_id AND workspace_id=w FOR UPDATE;SELECT * INTO r FROM hiring_lifecycle_requests WHERE id=p_request AND workspace_id=w FOR UPDATE;
 IF r.status='executed' THEN RETURN r.result;END IF;
 PERFORM public.hiring_lifecycle_revalidate(w,p_request,'execute');
 IF r.status<>'approved' OR r.revision<>p_revision OR EXISTS(SELECT 1 FROM hiring_lifecycle_steps WHERE request_id=r.id AND status<>'approved') THEN RAISE EXCEPTION 'Aprovação completa e revisão atual são obrigatórias.';END IF;
 PERFORM set_config('app.hiring_lifecycle',r.id::text,true);
 IF r.kind='end_employment' THEN
 UPDATE people_allocations SET ends_at=least(coalesce(ends_at,r.effective_date),r.effective_date),period_override_reason=r.reason WHERE hiring_engagement_id=r.engagement_id AND workspace_id=w AND status::text IN('active','paused');
 UPDATE hiring_engagements SET ends_at=r.effective_date,revision=revision+1,ended_by=auth.uid(),ended_at=(r.effective_date+1)::timestamp AT TIME ZONE 'America/Sao_Paulo',end_reason=r.reason WHERE id=r.engagement_id;
 UPDATE workspace_invites SET expires_at=least(expires_at,(r.effective_date+1)::timestamp AT TIME ZONE 'America/Sao_Paulo') WHERE hiring_engagement_id=r.engagement_id AND workspace_id=w AND accepted_at IS NULL;
 IF r.effective_date<(now() AT TIME ZONE 'America/Sao_Paulo')::date THEN
 PERFORM set_config('app.hiring_grant','on',true);
 DELETE FROM user_permission_sets ups USING hiring_access_grants g WHERE g.engagement_id=r.engagement_id AND g.workspace_id=w AND ups.id=g.assignment_id AND ups.user_id=g.user_id AND ups.set_id=g.set_id AND ups.workspace_id=w;
 UPDATE hiring_access_grants SET revoked_at=now() WHERE engagement_id=r.engagement_id AND workspace_id=w AND revoked_at IS NULL;PERFORM set_config('app.hiring_grant','off',true);END IF;
 ELSE SELECT * INTO a FROM people_allocations WHERE id=r.allocation_id AND workspace_id=w FOR UPDATE;
 IF r.kind<>'renew' THEN UPDATE people_allocations SET ends_at=r.effective_date,period_override_reason=r.reason WHERE id=a.id;END IF;
 IF r.kind IN('renew','replace') THEN SELECT * INTO b FROM hiring_engagements WHERE id=CASE WHEN r.kind='replace' THEN r.replacement_id ELSE r.engagement_id END AND workspace_id=w;
 IF r.kind='renew' THEN SELECT * INTO old_e FROM hiring_engagements WHERE id=r.engagement_id AND workspace_id=w;
 INSERT INTO hiring_engagements(workspace_id,person_id,job_id,purpose,employment_type,legal_entity_id,commercial_contract_id,purchase_contract_id,model_version_id,starts_at,ends_at,created_by,lifecycle_predecessor_id,lifecycle_request_id) VALUES(w,old_e.person_id,old_e.job_id,old_e.purpose,old_e.employment_type,old_e.legal_entity_id,old_e.commercial_contract_id,old_e.purchase_contract_id,old_e.model_version_id,r.starts_at,r.ends_at,auth.uid(),old_e.id,r.id) RETURNING id INTO new_e;
 SELECT * INTO b FROM hiring_engagements WHERE id=new_e;SELECT * INTO g FROM hiring_access_grants WHERE engagement_id=old_e.id AND workspace_id=w AND revoked_at IS NULL;
 IF g.id IS NOT NULL THEN SELECT * INTO v FROM hiring_access_model_versions WHERE id=b.model_version_id;PERFORM set_config('app.hiring_grant','on',true);
 INSERT INTO permission_sets(owner_id,workspace_id,module,name,description,is_system) VALUES(w,w,'__hiring__','Vínculo '||new_e::text,v.name||' · renovação aprovada',false) RETURNING id INTO new_set;
 INSERT INTO permission_set_items(set_id,permission_key) SELECT new_set,k FROM unnest(v.permission_keys)k;
 INSERT INTO user_permission_sets(user_id,owner_id,workspace_id,set_id) VALUES(g.user_id,w,w,new_set) RETURNING id INTO assignment;
 INSERT INTO hiring_access_grants(workspace_id,engagement_id,user_id,set_id,assignment_id) VALUES(w,new_e,g.user_id,new_set,assignment);PERFORM set_config('app.hiring_grant','off',true);END IF;END IF;
 IF a.id IS NOT NULL THEN INSERT INTO people_allocations(workspace_id,owner_id,assigned_to,person_id,project_id,contract_id,purchase_contract_id,hiring_engagement_id,starts_at,ends_at,allocation_pct,status,can_track_time,period_override_reason,lifecycle_request_id,lifecycle_predecessor_id,billable_rate,cost_rate,currency,hours_per_week,hours_per_month,service_id,role_title,calendar,competencies,manager_id,contracting_preset_id,overbook_justification,notes) VALUES(w,a.owner_id,a.assigned_to,b.person_id,a.project_id,b.commercial_contract_id,b.purchase_contract_id,b.id,r.starts_at,r.ends_at,a.allocation_pct,'active',a.can_track_time,r.reason,r.id,a.id,a.billable_rate,a.cost_rate,a.currency,a.hours_per_week,a.hours_per_month,a.service_id,a.role_title,a.calendar,a.competencies,a.manager_id,a.contracting_preset_id,CASE WHEN r.overlap THEN r.reason ELSE a.overbook_justification END,a.notes) RETURNING id INTO newid;END IF;END IF;
 UPDATE hiring_engagements SET revision=revision+1 WHERE id=r.engagement_id;END IF;
 result_value:=jsonb_build_object('allocation_id',newid,'engagement_id',new_e,'effective_date',r.effective_date,'financial_cancelled',false);
 UPDATE hiring_lifecycle_requests SET status='executed',revision=revision+1,result=result_value,executed_at=now() WHERE id=r.id;
 INSERT INTO hiring_employment_events(workspace_id,engagement_id,actor_id,kind,detail) VALUES(w,r.engagement_id,auth.uid(),'lifecycle_executed',jsonb_build_object('request_id',r.id,'kind',r.kind,'effective_date',r.effective_date,'result',result_value,'previous_hash',r.source_hash));PERFORM set_config('app.hiring_lifecycle','',true);RETURN result_value;
END $$;
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_context(w uuid,p_engagement uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE e hiring_engagements;BEGIN
 IF NOT public.hiring_lifecycle_access(w,p_engagement,'view') THEN RAISE EXCEPTION 'Sem permissão para ciclo.' USING ERRCODE='42501';END IF;SELECT * INTO e FROM hiring_engagements WHERE id=p_engagement AND workspace_id=w;
 RETURN jsonb_build_object('enabled',coalesce((SELECT lifecycle_gate_enabled FROM hiring_workspace_settings WHERE workspace_id=w),false),'actor_id',auth.uid(),
 'allocations',coalesce((SELECT jsonb_agg(jsonb_build_object('id',a.id,'engagement_id',a.hiring_engagement_id,'project_name',CASE WHEN a.project_id IS NULL THEN 'Sem projeto' WHEN public.work_record_access('techprojects.projects',a.project_id,'view') THEN coalesce(pr.name,'Projeto') ELSE 'Projeto sem acesso' END,'starts_at',a.starts_at,'ends_at',a.ends_at)) FROM people_allocations a LEFT JOIN projects pr ON pr.id=a.project_id AND pr.workspace_id=w WHERE a.hiring_engagement_id=e.id AND a.workspace_id=w AND a.status::text IN('active','paused') AND public.hr_record_access('person_allocations','view',e.person_id) AND(a.project_id IS NULL OR public.work_record_access('techprojects.projects',a.project_id,'view'))),'[]'),
 'replacements',coalesce((SELECT jsonb_agg(jsonb_build_object('id',b.id,'name',pe.full_name,'starts_at',b.starts_at,'ends_at',b.ends_at)) FROM hiring_engagements b JOIN people pe ON pe.id=b.person_id AND pe.workspace_id=w WHERE b.workspace_id=w AND b.id<>e.id AND b.person_id<>e.person_id AND b.status='active' AND b.legal_entity_id=e.legal_entity_id AND b.commercial_contract_id IS NOT DISTINCT FROM e.commercial_contract_id AND b.purpose=e.purpose AND public.hr_record_access('people','view',b.person_id)),'[]'),
 'requests',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'kind',r.kind,'status',r.status,'effective_date',r.effective_date,'reason',r.reason,'revision',r.revision,'requested_by',r.requested_by,'next_approver',(SELECT approver_id FROM hiring_lifecycle_steps WHERE request_id=r.id AND status='pending' ORDER BY position LIMIT 1),'steps',(SELECT jsonb_agg(jsonb_build_object('stage',s.stage,'status',s.status,'approver_id',s.approver_id,'note',s.note) ORDER BY position) FROM hiring_lifecycle_steps s WHERE s.request_id=r.id)) ORDER BY r.created_at DESC) FROM (SELECT id,kind,status,effective_date,reason,revision,requested_by,created_at FROM hiring_lifecycle_requests WHERE engagement_id=e.id AND workspace_id=w ORDER BY created_at DESC LIMIT 50)r),'[]'));
END $$;
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_time_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE a people_allocations;BEGIN
 FOR a IN SELECT x.* FROM people_allocations x JOIN people pe ON pe.id=x.person_id WHERE x.workspace_id=NEW.workspace_id AND(x.id=NEW.allocation_id OR(NEW.allocation_id IS NULL AND pe.profile_id=NEW.user_id AND x.project_id=NEW.project_id)) AND x.hiring_engagement_id IS NOT NULL LOOP
 PERFORM id FROM hiring_engagements WHERE id=a.hiring_engagement_id FOR UPDATE;SELECT * INTO a FROM people_allocations WHERE id=a.id;
 IF EXISTS(SELECT 1 FROM hiring_workspace_settings WHERE workspace_id=a.workspace_id AND lifecycle_gate_enabled) AND NEW.allocation_id=a.id AND(NEW.entry_date<a.starts_at OR(a.ends_at IS NOT NULL AND NEW.entry_date>a.ends_at)) THEN RAISE EXCEPTION 'Horas fora do período desta alocação; selecione origem válida.';END IF;END LOOP;
 IF EXISTS(SELECT 1 FROM hiring_workspace_settings WHERE workspace_id=NEW.workspace_id AND lifecycle_gate_enabled) AND NEW.allocation_id IS NULL AND EXISTS(SELECT 1 FROM people_allocations x JOIN people pe ON pe.id=x.person_id WHERE x.workspace_id=NEW.workspace_id AND x.project_id=NEW.project_id AND pe.profile_id=NEW.user_id AND x.hiring_engagement_id IS NOT NULL) AND NOT EXISTS(SELECT 1 FROM people_allocations x JOIN people pe ON pe.id=x.person_id JOIN hiring_engagements e ON e.id=x.hiring_engagement_id WHERE x.workspace_id=NEW.workspace_id AND x.project_id=NEW.project_id AND pe.profile_id=NEW.user_id AND x.status::text='active' AND x.can_track_time AND x.starts_at<=NEW.entry_date AND(x.ends_at IS NULL OR x.ends_at>=NEW.entry_date) AND e.starts_at<=NEW.entry_date AND(e.ends_at IS NULL OR e.ends_at>=NEW.entry_date)) THEN RAISE EXCEPTION 'Horas posteriores ao corte sem origem válida.';END IF;RETURN NEW;
END $$;
CREATE TRIGGER zzzzzzz_hiring_lifecycle_time BEFORE INSERT OR UPDATE ON public.project_time_entries FOR EACH ROW EXECUTE FUNCTION public.hiring_lifecycle_time_guard();
CREATE OR REPLACE FUNCTION public.hiring_offboarding_guard(w uuid,p_person uuid,p_actor uuid,p_action text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM hiring_workspace_settings WHERE workspace_id=w AND lifecycle_gate_enabled) THEN RETURN true;END IF;
 IF p_action NOT IN('terminate_contracts','close_allocations','revoke_access','cancel_payable_schedules') OR NOT EXISTS(SELECT 1 FROM workspace_members WHERE workspace_id=w AND user_id=p_actor AND status='active') OR NOT EXISTS(SELECT 1 FROM profiles WHERE id=p_actor AND active_workspace_id=w) OR NOT EXISTS(SELECT 1 FROM people WHERE id=p_person AND workspace_id=w) THEN RAISE EXCEPTION 'Responsável sem autorização atual para esta pessoa.' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM hiring_engagements WHERE person_id=p_person AND workspace_id=w) THEN RAISE EXCEPTION 'LIFECYCLE_REVIEW: use prévia e aprovação por origem. Compromissos exigem plano Financeiro separado com gestor Financeiro e CEO; cancelamento amplo bloqueado.';END IF;RETURN true;END $$;
CREATE OR REPLACE FUNCTION public.hiring_lifecycle_financial_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 IF NEW.status::text='cancelled' AND OLD.status::text<>'cancelled' AND OLD.direction::text='payable' AND EXISTS(SELECT 1 FROM hiring_workspace_settings WHERE workspace_id=OLD.workspace_id AND lifecycle_gate_enabled) AND EXISTS(SELECT 1 FROM hiring_engagements e WHERE e.workspace_id=OLD.workspace_id AND(e.purchase_contract_id=OLD.contract_id OR e.person_id::text=OLD.metadata->>'person_id' OR e.id::text=OLD.metadata->>'hiring_engagement_id')) THEN RAISE EXCEPTION 'FINANCE_LIFECYCLE_REVIEW: cancelamento bloqueado até plano Financeiro explícito revisado por gestor Financeiro e CEO; preserve pagamentos e competência trabalhada.';END IF;RETURN NEW;END $$;
CREATE TRIGGER zzzzzzz_hiring_lifecycle_finance BEFORE UPDATE ON public.financial_entries FOR EACH ROW EXECUTE FUNCTION public.hiring_lifecycle_financial_guard();
REVOKE ALL ON FUNCTION public.hiring_lifecycle_validate(uuid,uuid,uuid,text,date,date,date,uuid,boolean,text,uuid,text),public.hiring_lifecycle_revalidate(uuid,uuid,text),public.hiring_lifecycle_document(uuid,uuid,uuid,uuid,date,date),public.hiring_lifecycle_mutation_guard(),public.hiring_lifecycle_time_guard(),public.hiring_lifecycle_financial_guard() FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.hiring_offboarding_guard(uuid,uuid,uuid,text) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.hiring_offboarding_guard(uuid,uuid,uuid,text) TO service_role;
REVOKE ALL ON FUNCTION public.hiring_lifecycle_preview(uuid,uuid,uuid,text,date,date,date,uuid,boolean,text),public.hiring_lifecycle_request(uuid,uuid,uuid,text,date,date,date,uuid,boolean,text,text),public.hiring_lifecycle_decide(uuid,uuid,integer,text,text),public.hiring_lifecycle_execute(uuid,uuid,integer),public.hiring_lifecycle_context(uuid,uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.hiring_lifecycle_preview(uuid,uuid,uuid,text,date,date,date,uuid,boolean,text),public.hiring_lifecycle_request(uuid,uuid,uuid,text,date,date,date,uuid,boolean,text,text),public.hiring_lifecycle_decide(uuid,uuid,integer,text,text),public.hiring_lifecycle_execute(uuid,uuid,integer),public.hiring_lifecycle_context(uuid,uuid) TO authenticated;
CREATE OR REPLACE FUNCTION public.hiring_set_live(s uuid,u uuid,w uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT NOT EXISTS(SELECT 1 FROM permission_sets WHERE id=s AND module='__hiring__') OR EXISTS(SELECT 1 FROM hiring_access_grants g JOIN hiring_engagements e ON e.id=g.engagement_id JOIN people pe ON pe.id=e.person_id JOIN hiring_access_model_versions v ON v.id=e.model_version_id JOIN ats_jobs j ON j.id=e.job_id WHERE v.role_id=j.hiring_role_id AND g.set_id=s AND g.user_id=u AND g.workspace_id=w AND e.workspace_id=w AND g.revoked_at IS NULL AND e.status='active' AND pe.profile_id=u AND pe.status='active' AND NOT pe.archived AND(pe.hire_date IS NULL OR pe.hire_date<=(now() AT TIME ZONE 'America/Sao_Paulo')::date) AND e.starts_at<=(now() AT TIME ZONE 'America/Sao_Paulo')::date AND(e.ends_at IS NULL OR e.ends_at>=(now() AT TIME ZONE 'America/Sao_Paulo')::date)) $$;
CREATE OR REPLACE FUNCTION public.hiring_allocation_scope(w uuid,p uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT public.is_workspace_member(w,auth.uid()) AND public.work_access_context()->>'workspace'=w::text AND(public.is_workspace_admin_v2(w,auth.uid()) OR NOT EXISTS(SELECT 1 FROM hiring_access_grants WHERE user_id=auth.uid() AND workspace_id=w AND revoked_at IS NULL) OR EXISTS(SELECT 1 FROM hiring_access_grants g JOIN hiring_engagements e ON e.id=g.engagement_id JOIN hiring_access_model_versions v ON v.id=e.model_version_id WHERE g.user_id=auth.uid() AND g.workspace_id=w AND g.revoked_at IS NULL AND NOT v.allocation_only AND public.hiring_set_live(g.set_id,g.user_id,w)) OR EXISTS(SELECT 1 FROM people_allocations a JOIN people pe ON pe.id=a.person_id JOIN hiring_engagements e ON e.id=a.hiring_engagement_id JOIN hiring_access_grants g ON g.engagement_id=e.id WHERE a.project_id=p AND a.workspace_id=w AND pe.profile_id=auth.uid() AND a.status='active' AND a.can_track_time AND a.starts_at<=(now() AT TIME ZONE 'America/Sao_Paulo')::date AND(a.ends_at IS NULL OR a.ends_at>=(now() AT TIME ZONE 'America/Sao_Paulo')::date) AND g.revoked_at IS NULL AND public.hiring_set_live(g.set_id,auth.uid(),w))) $$;
CREATE OR REPLACE FUNCTION public.hiring_employment_end(w uuid,p_engagement uuid,p_reason text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE e public.hiring_engagements;BEGIN
 SELECT * INTO e FROM hiring_engagements WHERE id=p_engagement AND workspace_id=w FOR UPDATE;
 IF e.id IS NULL OR NOT public.hiring_employment_access(w,'techpeople.employment.manage.workspace') OR NOT public.hr_record_access('people','update',e.person_id) THEN RAISE EXCEPTION 'Sem permissão para encerrar vínculo.' USING ERRCODE='42501';END IF;
 IF EXISTS(SELECT 1 FROM hiring_workspace_settings WHERE workspace_id=w AND lifecycle_gate_enabled) THEN RAISE EXCEPTION 'Use o ciclo governado; encerramento legado bloqueado antes de revogar acessos.' USING ERRCODE='42501';END IF;
 IF length(trim(coalesce(p_reason,'')))<10 THEN RAISE EXCEPTION 'Informe motivo do encerramento.';END IF;IF e.status='ended' THEN RETURN;END IF;
 UPDATE people_allocations SET status='ended',can_track_time=false WHERE hiring_engagement_id=e.id;DELETE FROM user_permission_sets ups USING hiring_access_grants g WHERE g.engagement_id=e.id AND ups.id=g.assignment_id AND ups.user_id=g.user_id AND ups.set_id=g.set_id AND ups.workspace_id=w;
 UPDATE hiring_access_grants SET revoked_at=now() WHERE engagement_id=e.id AND revoked_at IS NULL;UPDATE workspace_invites SET expires_at=least(expires_at,now()) WHERE hiring_engagement_id=e.id AND accepted_at IS NULL;
 UPDATE hiring_engagements SET status='ended',ended_at=now(),ended_by=auth.uid(),end_reason=trim(p_reason),revision=revision+1 WHERE id=e.id;INSERT INTO hiring_employment_events(workspace_id,engagement_id,actor_id,kind,detail) VALUES(w,e.id,auth.uid(),'ended',jsonb_build_object('reason',trim(p_reason)));END $$;
NOTIFY pgrst,'reload schema';
